@startuml

class Customer {
  + Name : string
}

class Broker {
  + Name : string
}

class InsuranceProduct {
  + Name : string
  + Price : float
}

class Offer {
  + Date : date
}

class Contract {
  + Date : date
  + BillingCycle : string
}

class ClaimCase {
  + CaseNumber : string
  + Status : string
}

class Estimator {
  + Name : string
  + Expertise : string
}

class EstimatorReport {
  + Date : date
  + Content : string
}

class CompensationDecision {
  + EligibleCosts : float
}

class Payment {
  + Amount : float
  + Date : date
}

Broker "1" -- "0..*" Customer : manages
Customer "1" -- "0..*" Offer : receives
Customer "1" -- "0..*" Contract : signs
Customer "1" -- "0..*" ClaimCase : files
Customer "1" -- "1" Payment : receives
Offer "0..*" -- "1" InsuranceProduct : based on
Offer "0..*" -- "1" Customer : for
Contract "1" -- "1" InsuranceProduct : covers
Contract "1" -- "0..*" ClaimCase : results in
ClaimCase "1" *-- "1..*" EstimatorReport : contains
Estimator "1" -- "0..*" EstimatorReport : issues
ClaimCase "1" -- "0..1" CompensationDecision : results in
CompensationDecision "1" -- "1" Payment : triggers

@enduml

